/** Terminates the clients, waits for each server to see its sockets close, then stops it. */
export async function stopAfterClose(
  clientsToStop: WebSocket[],
  serversToStop: Array<Pick<HalServer, 'wss' | 'stop'>>
): Promise<void> {
  for (const client of clientsToStop.splice(0)) client.terminate();
  for (const hal of serversToStop.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

